import json
rows=json.loads(context)
daily={}
for r in rows:
    t=r['account_type']
    if 'Deposits' in t or 'Withdrawals' in t:
        daily.setdefault(r['record_date'], 0)
        amount=int(r['open_today_bal'])
        daily[r['record_date']] += amount if 'Deposits' in t else -amount
print(sum(daily.values()))
